const settings = await sdk.settings.get();
let count = (await sdk.storage.get('count')) || 0;
await sdk.status.set('usage', `초안 ${count}회`);
async function draft(arg = '') {
  const ctx = await sdk.context.get();
  await sdk.composer.setText(`${settings.prefix || '현재 작업 진행 상황을 요약하고 다음 단계를 제안해 주세요.'}\n${arg}`);
  count++;
  await sdk.storage.set('count', count);
  await sdk.status.set('usage', `초안 ${count}회 · ${ctx.model || '모델 미선택'}`);
}
await sdk.commands.register({name: 'summary', description: '작업 요약 초안', args: '[추가 지침]'}, draft);
await sdk.composer.registerAction({id: 'summary', label: '요약 초안'}, () => draft());
await sdk.events.on(async event => {
  if (event.type === 'run_finished') await sdk.status.set('run', event.status === 'error' ? '작업 실패' : '작업 완료');
});
await sdk.log('세션 도우미 시작');
